mapper.update:
update users
set status = #{status}
where user_idx = #{userIdx}

mapper.insert:
insert into embedded_user (
  embed_user_idx, user_idx, start_date, end_date, reason
) values (
  seq_embed_user.nextval,
  #{userIdx},
  to_date(#{startDate}, 'yyyy-mm-dd'),
  case
    when #{endDate} is null or #{endDate} = '' then null
    else to_date(#{endDate}, 'yyyy-mm-dd')
  end,
  #{reason}
)

mapper.select:
select count(*)
from cert
where user_idx = #{userIdx}
  and cert_type = #{certType}
